// NODE GABUNGAN (dirakit oleh scripts/build_workflows.py). Setiap langkah = satu file di n8n/code/.
// Rujukan $('Nama Node') ditulis eksplisit agar task runner n8n mengirim data node tersebut.
const __nyata = { "Terima Panel": () => $('Terima Panel'), "Baca Sheet Panel": () => $('Baca Sheet Panel'), "Catat Gagal (Panel)": () => $('Catat Gagal (Panel)'), "Tulis Log Error (Panel)": () => $('Tulis Log Error (Panel)'), "Kirim Respons Gagal (Panel)": () => $('Kirim Respons Gagal (Panel)'), "Kirim Panel": () => $('Kirim Panel') };
const __asli = (n) => (n in __nyata ? __nyata[n]() : $(n));
const __peta = {"Siapkan Log Error (Panel)": "Catat Gagal (Panel)", "Data Log (Panel)": "Catat Gagal (Panel)", "Susun Baris Log (Panel)": "Catat Gagal (Panel)"};
const __lokal = ["Validasi Panel", "Olah Sheet Panel", "Susun Panel"];
const __hasil = {};
const __tidakJalan = (n) => ({ isExecuted: false, first: () => { throw new Error('Langkah ' + n + ' tidak dijalankan.'); }, all: () => [] });
function __ref(n) {
  if (n in __hasil) return { isExecuted: true, first: () => __hasil[n][0], all: () => __hasil[n] };
  if (__lokal.includes(n)) return __tidakJalan(n);
  if (n in __peta) {
    const nyata = __asli(__peta[n]);
    if (!nyata.isExecuted) return __tidakJalan(n);
    const j = (nyata.first().json.__langkah || {})[n];
    if (j === undefined) return __tidakJalan(n);
    return { isExecuted: true, first: () => ({ json: j }), all: () => [{ json: j }] };
  }
  return __asli(n);
}
const __masuk = (items) => ({ first: () => items[0], all: () => items });
function __jalan(nama, fn, items) {
  try {
    const out = fn(__ref, __masuk(items));
    __hasil[nama] = out;
    return out;
  } catch (e) {
    e.message = '[' + nama + '] ' + e.message;
    throw e;
  }
}
const __selesai = (json) => [{
  json: { ...json, __langkah: Object.fromEntries(Object.entries(__hasil).map(([k, v]) => [k, v[0] && v[0].json])) },
}];
let __data = $input.all();

// ===== langkah: Validasi Panel =====
__data = __jalan("Validasi Panel", function ($, $input) {
// WF-02 node "Validasi Panel" (GET /panel?peran=...). Mode: Run Once for All Items.
const q = $input.first().json.query || {};
const peran = String(q.peran ?? '').trim().toLowerCase();
const valid = ['staf', 'ae_a', 'ae_b', 'admin'].includes(peran);
// ekspor=1: sertakan baris lengkap Prospek dan Histori untuk Ekspor CSV (FR-19).
const ekspor = String(q.ekspor ?? '') === '1';
return [{ json: { valid, pesan: valid ? '' : 'Peran tidak dikenal. Gunakan staf, ae_a, ae_b, atau admin.', peran, ekspor } }];

}, __asli("Terima Panel").all());
{ const __out = __data[0].json; const __henti = (__out.valid ? null : { aksi: 'tolak', kode: 400, body: { status: 'ditolak', pesan: __out.pesan } }); if (__henti) return __selesai(__henti); }

// ===== langkah: Olah Sheet Panel =====
__data = __jalan("Olah Sheet Panel", function ($, $input) {
// Node "Olah Data Sheet" (dipakai WF-01, WF-02, WF-03). Mode: Run Once for All Items.
// Mengubah respons spreadsheets.get (beberapa sheet dalam satu panggilan) menjadi:
//   tabel[sheet]  = daftar baris sebagai objek {kolom: nilai, _baris: nomor baris di sheet (1 = header)}
//   header[sheet] = urutan kolom (dipakai saat menulis)
//   gid[sheet]    = sheetId numerik (dipakai appendCells dan updateCells)
// SHEET_WAJIB diisi saat dirakit.
const SHEET_WAJIB = [
  "Konfigurasi",
  "Prospek",
  "Percakapan",
  "Antrean_Staf",
  "Draf",
  "Histori",
  "Log_Error"
];

const res = $input.first().json;
const tabel = {};
const header = {};
const gid = {};

for (const sh of res.sheets || []) {
  const judul = sh.properties.title;
  gid[judul] = sh.properties.sheetId;
  const baris = ((sh.data && sh.data[0] && sh.data[0].rowData) || []).map((r) =>
    (r.values || []).map((c) => (c && c.formattedValue != null ? String(c.formattedValue) : ''))
  );
  const kolom = (baris[0] || []).map((k) => k.trim());
  header[judul] = kolom;
  tabel[judul] = baris
    .map((r, i) => ({ r, nomor: i + 1 }))
    .slice(1)
    .filter(({ r }) => r.some((v) => v.trim() !== ''))
    .map(({ r, nomor }) => ({ ...Object.fromEntries(kolom.map((k, i) => [k, r[i] ?? ''])), _baris: nomor }));
}

const hilang = SHEET_WAJIB.filter((s) => !(s in tabel) || header[s].length === 0);
if (hilang.length) throw new Error('Sheet tidak ditemukan atau tanpa header: ' + hilang.join(', '));

return [{ json: { tabel, header, gid } }];

}, $input.all());

// ===== langkah: Susun Panel =====
__data = __jalan("Susun Panel", function ($, $input) {
// SIMULASI MSI — Penyusun permintaan spreadsheets.batchUpdate (WF-01, WF-03).
// Semua perubahan satu permintaan dikirim dalam satu batchUpdate, yang diterapkan Google secara atomik.
// D = keluaran node "Olah Data Sheet" ({tabel, header, gid}). Baris module.exports hanya untuk uji unit.

const AKTOR = { staf: 'Staf', ae_a: 'AE A', ae_b: 'AE B', admin: 'Admin' };
const STATUS_PIPELINE = ['Baru', 'Kualifikasi', 'Follow-up', 'Penawaran draf'];
const STATUS_DRAF = ['Menunggu persetujuan', 'Disetujui', 'Ditolak', 'Siap kirim (simulasi)', 'Terkirim (simulasi)'];

// E1: arsip = aktif FALSE; baris tanpa nilai aktif (data sebelum E1) dianggap aktif.
function pesertaAktif(p) {
  return String((p && p.aktif) ?? '').trim().toUpperCase() !== 'FALSE';
}

function nomorBerikut(baris, kolom) {
  return Math.max(0, ...baris.map((r) => parseInt(String(r[kolom] || '').replace(/\D/g, ''), 10) || 0)) + 1;
}

function idBaru(awalan, nomor) {
  return awalan + String(nomor).padStart(4, '0');
}

function sel(v) {
  return typeof v === 'boolean'
    ? { userEnteredValue: { boolValue: v } }
    : { userEnteredValue: { stringValue: v == null ? '' : String(v) } };
}

// Menambah baris di akhir sheet; kolom mengikuti urutan header sheet itu sendiri.
function tambahBaris(D, sheet, daftar) {
  const kolom = D.header[sheet];
  if (!kolom) throw new Error(`Sheet ${sheet} tidak dibaca.`);
  for (const b of daftar) {
    const asing = Object.keys(b).filter((k) => !kolom.includes(k));
    if (asing.length) throw new Error(`Kolom ${asing.join(', ')} tidak ada di header sheet ${sheet}.`);
  }
  return {
    appendCells: {
      sheetId: D.gid[sheet],
      rows: daftar.map((b) => ({ values: kolom.map((k) => sel(b[k])) })),
      fields: 'userEnteredValue',
    },
  };
}

// Mengubah sel tertentu pada baris yang sudah ada (objek dari tabel, membawa _baris).
function ubahSel(D, sheet, objek, perubahan) {
  if (!objek || !objek._baris || objek._baris < 2) throw new Error(`Baris ${sheet} tidak valid untuk diubah.`);
  return Object.entries(perubahan).map(([k, v]) => {
    const c = D.header[sheet].indexOf(k);
    if (c < 0) throw new Error(`Kolom ${k} tidak ada di header sheet ${sheet}.`);
    return {
      updateCells: {
        range: {
          sheetId: D.gid[sheet],
          startRowIndex: objek._baris - 1,
          endRowIndex: objek._baris,
          startColumnIndex: c,
          endColumnIndex: c + 1,
        },
        rows: [{ values: [sel(v)] }],
        fields: 'userEnteredValue',
      },
    };
  });
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { AKTOR, STATUS_PIPELINE, STATUS_DRAF, pesertaAktif, nomorBerikut, idBaru, sel, tambahBaris, ubahSel };
}

// SIMULASI MSI — Aturan tiket eskalasi (POST /tiket di WF-06): ambil, jawab lewat draf, selesai.
// Fungsi murni; diuji di aturan_tiket.test.js. Baris module.exports hanya untuk uji unit.
// Saat dirakit, sheet_tulis.js ditempel di atas file ini (AKTOR, nomorBerikut, idBaru, tambahBaris, ubahSel).
// Siklus: Baru -> Ditangani -> Selesai. Selesai tidak bisa dibuka lagi. Tidak ada kolom baru:
// catatan penyelesaian dan jejak perubahan disimpan di Histori (jenis ubah_tiket).
// "Jawab lewat draf" membuat Draf berstatus Menunggu persetujuan yang ditandai di kolom catatan
// ("Jawaban staf atas T0001"); /draf/kirim memakai penanda itu untuk menutup tiket saat draf terkirim.

const AKSI_TIKET = ['ambil', 'jawab', 'selesai'];
const PENANDA_JAWABAN = 'Jawaban staf atas ';

function teksTiket(v) {
  return String(v ?? '').trim();
}

// Id tiket yang dijawab oleh sebuah draf, dibaca dari penanda di awal kolom catatan; null bila bukan draf jawaban staf.
function tiketDariDraf(draf) {
  const m = String((draf && draf.catatan) || '').match(/^Jawaban staf atas (T\d{4,})/);
  return m ? m[1] : null;
}

function validasiTiket(body) {
  const b = body || {};
  const id_tiket = teksTiket(b.id_tiket).toUpperCase();
  const aksi = teksTiket(b.aksi).toLowerCase();
  const oleh = teksTiket(b.oleh).toLowerCase();
  const catatan = teksTiket(b.catatan);
  const jawaban = teksTiket(b.jawaban);
  const pesan = [];
  if (!/^T\d{4,}$/.test(id_tiket)) pesan.push('id_tiket tidak valid.');
  if (!AKSI_TIKET.includes(aksi)) pesan.push('Aksi harus ambil, jawab, atau selesai.');
  if (oleh !== 'staf') pesan.push('Hanya peran staf yang boleh menangani tiket.');
  if (aksi === 'selesai' && !catatan) pesan.push('Catatan penyelesaian wajib diisi.');
  if (aksi === 'jawab' && !jawaban) pesan.push('Isi jawaban untuk calon peserta wajib diisi.');
  if (jawaban.length > 1500) pesan.push('Jawaban maksimal 1500 karakter.');
  if (catatan.length > 300) pesan.push('Catatan maksimal 300 karakter.');
  return { valid: pesan.length === 0, pesan: pesan.join(' '), id_tiket, aksi, oleh, catatan, jawaban };
}

function tolakTiket(pesan) {
  return { boleh: false, pesan };
}

// Draf jawaban staf yang masih hidup (bukan Ditolak) untuk tiket ini.
function drafJawabanAktif(D, idTiket) {
  return D.tabel.Draf.find((d) => tiketDariDraf(d) === idTiket && String(d.status).trim() !== 'Ditolak');
}

// D = Olah Data Sheet (Antrean_Staf, Percakapan, Draf, Histori); m = validasiTiket.
function prosesTiket(D, m, waktu) {
  const tiket = D.tabel.Antrean_Staf.find((t) => String(t.id_tiket).trim().toUpperCase() === m.id_tiket);
  if (!tiket) return tolakTiket(`Tiket ${m.id_tiket} tidak ditemukan.`);
  const statusLama = String(tiket.status).trim() || 'Baru';
  if (statusLama === 'Selesai') return tolakTiket(`Tiket ${m.id_tiket} sudah Selesai dan tidak bisa diubah lagi.`);

  const aktor = AKTOR[m.oleh];
  const percakapan = D.tabel.Percakapan.find((c) => String(c.id_percakapan).trim() === String(tiket.id_percakapan).trim()) || {};
  const idProspek = String(percakapan.id_prospek || '').trim();
  let nomorH = nomorBerikut(D.tabel.Histori, 'id_histori');
  const histori = (jenis, nilai_lama, nilai_baru, catatan) => ({
    id_histori: idBaru('H', nomorH++), waktu, id_prospek: idProspek, aktor, jenis, nilai_lama, nilai_baru, catatan,
  });

  if (m.aksi === 'ambil') {
    if (statusLama !== 'Baru') return tolakTiket(`Tiket ${m.id_tiket} sudah ${statusLama} oleh ${tiket.ditangani_oleh || 'staf lain'}.`);
    const h = histori('ubah_tiket', statusLama, 'Ditangani', `${m.id_tiket}${m.catatan ? '; ' + m.catatan : ''}`);
    return {
      boleh: true,
      body_tulis: { requests: [...ubahSel(D, 'Antrean_Staf', tiket, { status: 'Ditangani', ditangani_oleh: aktor }), tambahBaris(D, 'Histori', [h])] },
      respons: { status: 'ok', id_tiket: m.id_tiket, status_tiket: 'Ditangani', pesan: `${m.id_tiket} sekarang ditangani ${aktor}.` },
    };
  }

  if (m.aksi === 'selesai') {
    const h = histori('ubah_tiket', statusLama, 'Selesai', `${m.id_tiket}; ${m.catatan}`);
    return {
      boleh: true,
      body_tulis: {
        requests: [...ubahSel(D, 'Antrean_Staf', tiket, { status: 'Selesai', ditangani_oleh: tiket.ditangani_oleh || aktor }), tambahBaris(D, 'Histori', [h])],
      },
      respons: { status: 'ok', id_tiket: m.id_tiket, status_tiket: 'Selesai', pesan: `${m.id_tiket} ditandai selesai.` },
    };
  }

  // jawab: jawaban manusia menjadi draf yang mengikuti alur persetujuan biasa.
  if (!idProspek) return tolakTiket(`Percakapan untuk tiket ${m.id_tiket} tidak ditemukan; draf tidak bisa dibuat.`);
  const ada = drafJawabanAktif(D, m.id_tiket);
  if (ada) return tolakTiket(`Tiket ${m.id_tiket} sudah punya draf jawaban ${ada.id_draf} (${ada.status}).`);
  const idDraf = idBaru('D', nomorBerikut(D.tabel.Draf, 'id_draf'));
  const draf = {
    id_draf: idDraf,
    id_prospek: idProspek,
    id_percakapan: tiket.id_percakapan,
    isi_draf: m.jawaban,
    status: 'Menunggu persetujuan',
    diputuskan_oleh: '',
    catatan: PENANDA_JAWABAN + m.id_tiket,
    dibuat: waktu,
    diputuskan: '',
  };
  const hs = [histori('draf_dibuat', '', idDraf, PENANDA_JAWABAN + m.id_tiket)];
  const requests = [tambahBaris(D, 'Draf', [draf])];
  if (statusLama === 'Baru') {
    requests.push(...ubahSel(D, 'Antrean_Staf', tiket, { status: 'Ditangani', ditangani_oleh: aktor }));
    hs.push(histori('ubah_tiket', 'Baru', 'Ditangani', `${m.id_tiket}; dijawab lewat ${idDraf}`));
  }
  requests.push(tambahBaris(D, 'Histori', hs));
  return {
    boleh: true,
    body_tulis: { requests },
    respons: {
      status: 'ok', id_tiket: m.id_tiket, status_tiket: 'Ditangani', id_draf: idDraf,
      pesan: `Draf jawaban ${idDraf} dibuat dan menunggu persetujuan. Tiket ${m.id_tiket} akan selesai otomatis setelah draf terkirim.`,
    },
  };
}

// Dipakai /draf/kirim: bila draf yang dikirim adalah jawaban staf, tutup tiketnya dalam batch yang sama.
// Mengembalikan { requests, histori } tambahan, atau null bila tidak ada tiket yang perlu ditutup.
function tutupTiketSaatTerkirim(D, draf, aktor, waktu, nomorHistori) {
  const idTiket = tiketDariDraf(draf);
  if (!idTiket || !D.tabel.Antrean_Staf) return null;
  const tiket = D.tabel.Antrean_Staf.find((t) => String(t.id_tiket).trim().toUpperCase() === idTiket);
  if (!tiket || String(tiket.status).trim() === 'Selesai') return null;
  return {
    requests: ubahSel(D, 'Antrean_Staf', tiket, { status: 'Selesai', ditangani_oleh: tiket.ditangani_oleh || aktor }),
    histori: {
      id_histori: idBaru('H', nomorHistori), waktu, id_prospek: draf.id_prospek, aktor, jenis: 'ubah_tiket',
      nilai_lama: String(tiket.status).trim() || 'Baru', nilai_baru: 'Selesai', catatan: `${idTiket}; selesai otomatis, jawaban ${draf.id_draf} terkirim`,
    },
  };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { tiketDariDraf, validasiTiket, prosesTiket, tutupTiketSaatTerkirim };
}

// WF-02 node "Susun Panel" (FR-12, FR-15; kontrak GET /panel Section 10). Mode: Run Once for All Items.
// Saat dirakit, isi n8n/code/sheet_tulis.js ditempel di atas bagian ini (AKTOR, STATUS_PIPELINE).
// Tanpa nilai penjualan (Section 2). AE hanya melihat prospek miliknya beserta tiket dan drafnya.
const { peran, ekspor } = $('Validasi Panel').first().json;
const { tabel: T, header } = $('Olah Sheet Panel').first().json;

const konfig = Object.fromEntries(T.Konfigurasi.map((r) => [String(r.kunci).trim(), String(r.nilai ?? '').trim()]));
const tanggal = konfig.TANGGAL_SIMULASI || '';

const semua = T.Prospek.filter((p) => String(p.id_prospek || '').trim());
const milikPeran = peran === 'ae_a' || peran === 'ae_b' ? semua.filter((p) => p.ae === AKTOR[peran]) : semua;
// E1: dashboard, tabel peserta, antrean, dan draf hanya memakai peserta aktif; arsip tetap ada di sheet dan ekspor.
const terlihat = milikPeran.filter(pesertaAktif);
const idTerlihat = new Set(terlihat.map((p) => p.id_prospek));
const namaProspek = Object.fromEntries(semua.map((p) => [p.id_prospek, p.nama_perusahaan]));
const hpProspek = Object.fromEntries(semua.map((p) => [p.id_prospek, p.no_hp_pic || '']));
const percakapan = Object.fromEntries(T.Percakapan.map((c) => [c.id_percakapan, c]));

const KOLOM_PROSPEK = [
  'id_prospek', 'nama_perusahaan', 'sektor', 'ae', 'status', 'kebutuhan', 'status_kebutuhan', 'tgl_tindak_lanjut', 'pengingat',
  'nama_pic', 'no_hp_pic', 'kategori', 'sumber', 'dibuat', 'diubah',
];
const prospek = terlihat.map((p) => Object.fromEntries(KOLOM_PROSPEK.map((k) => [k, p[k] ?? ''])));

const per_status = Object.fromEntries(STATUS_PIPELINE.map((s) => [s, terlihat.filter((p) => p.status === s).length]));
const per_ae = { 'AE A': 0, 'AE B': 0 };
for (const p of terlihat) if (p.ae in per_ae) per_ae[p.ae] += 1;

const antrean = T.Antrean_Staf.filter((t) => String(t.status).trim() !== 'Selesai')
  .map((t) => {
    const c = percakapan[t.id_percakapan] || {};
    return {
      id_tiket: t.id_tiket,
      id_percakapan: t.id_percakapan,
      id_prospek: c.id_prospek || '',
      nama_perusahaan: namaProspek[c.id_prospek] || '',
      pertanyaan: c.pertanyaan || '',
      jawaban: c.jawaban || '',
      alasan: t.alasan,
      status: String(t.status || '').trim() || 'Baru',
      ditangani_oleh: t.ditangani_oleh || '',
      waktu: t.waktu,
      // Opsi B: draf jawaban staf yang masih hidup untuk tiket ini (bila ada).
      draf_jawaban: (function () {
        const dj = T.Draf.filter((d) => tiketDariDraf(d) === t.id_tiket && String(d.status).trim() !== 'Ditolak').pop();
        return dj ? { id_draf: dj.id_draf, status: dj.status } : null;
      })(),
    };
  })
  .filter((t) => idTerlihat.has(t.id_prospek));

const daftarDraf = (status) =>
  T.Draf.filter((d) => String(d.status).trim() === status && idTerlihat.has(d.id_prospek))
    .map((d) => {
      const c = percakapan[d.id_percakapan] || {};
      return {
        id_draf: d.id_draf,
        id_prospek: d.id_prospek,
        nama_perusahaan: namaProspek[d.id_prospek] || '',
        no_hp_pic: hpProspek[d.id_prospek] || '', // E-03: tujuan tombol Kirim (simulasi), nomor dummy
        id_percakapan: d.id_percakapan || '',
        // Sumber draf: chat (follow-up AI), catatan_ae (draf penawaran AE), atau jawaban_staf (jawaban atas tiket).
        sumber: tiketDariDraf(d) ? 'jawaban_staf' : d.id_percakapan ? 'chat' : 'catatan_ae',
        id_tiket: tiketDariDraf(d) || '',
        pertanyaan: c.pertanyaan || '',
        isi_draf: d.isi_draf,
        catatan: d.catatan || '',
        dibuat: d.dibuat,
        diputuskan_oleh: d.diputuskan_oleh || '',
      };
    })
    .reverse(); // terbaru di atas

// Pengingat (FR-11): tanggal tindak lanjut sama dengan atau sebelum TANGGAL_SIMULASI.
const pengingat = [];
const tindak_lanjut_mendatang = [];
for (const p of terlihat) {
  const tgl = String(p.tgl_tindak_lanjut || '').trim();
  if (!tgl) continue;
  const butir = { id_prospek: p.id_prospek, nama_perusahaan: p.nama_perusahaan, ae: p.ae, tgl_tindak_lanjut: tgl };
  if (tanggal && tgl < tanggal) pengingat.push({ ...butir, keterangan: 'Terlewat' });
  else if (tgl === tanggal) pengingat.push({ ...butir, keterangan: 'Jatuh tempo hari ini' });
  else tindak_lanjut_mendatang.push(butir);
}
const urutTanggal = (a, b) => a.tgl_tindak_lanjut.localeCompare(b.tgl_tindak_lanjut);

// FR-19: baris lengkap sesuai header sheet (tanpa kolom bantu _baris), tersaring per peran.
const barisLengkap = (sheet, daftar) => daftar.map((r) => header[sheet].map((k) => r[k] ?? ''));
const dataEkspor = ekspor
  ? {
      // Ekspor memuat juga peserta yang diarsipkan (kolom aktif FALSE), karena arsip bukan penghapusan.
      prospek: { kolom: header.Prospek, baris: barisLengkap('Prospek', milikPeran) },
      histori: {
        kolom: header.Histori,
